#!/usr/bin/env node
/**
 * Write design tokens into `apps/web/src/index.css` and static brand consumers.
 *
 * CSS cannot import a JavaScript module, so the token table reaches the
 * stylesheet as generated bytes between two markers. The rest of `index.css`
 * — the body rules, the focus ring, the print stylesheet — is hand-written and
 * is not touched. Brand SVGs, manifest colours and the frame identity helper
 * are generated in the same pass; PNGs use `rasterize-brand-icons.mjs`.
 *
 * `apps/web/src/app/designTokens.test.ts` runs the same generator and fails if
 * the checked-in block differs, so "I forgot to regenerate" is a red test
 * rather than a shell and a conversation that disagree about what grey is.
 *
 *   node scripts/build/generate-design-tokens.mjs           # write
 *   node scripts/build/generate-design-tokens.mjs --check   # exit 1 if stale
 */
import { readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { brandArtifacts } from './brand-assets.mjs'

import {
  DESIGN_TOKENS_CSS_BEGIN,
  DESIGN_TOKENS_CSS_END,
  designTokensCss,
} from '../../packages/design-tokens/src/css.mjs'

const target = fileURLToPath(new URL('../../apps/web/src/index.css', import.meta.url))

/**
 * Replace the marked block, leaving every other byte alone.
 * @param {string} css
 * @returns {string}
 */
export function withGeneratedTokens(css) {
  const start = css.indexOf(DESIGN_TOKENS_CSS_BEGIN)
  const end = css.indexOf(DESIGN_TOKENS_CSS_END)
  if (start === -1 || end === -1 || end < start) {
    throw new Error(`index.css is missing the generated-token markers (${DESIGN_TOKENS_CSS_BEGIN})`)
  }
  return css.slice(0, start) + designTokensCss() + css.slice(end + DESIGN_TOKENS_CSS_END.length)
}

const targets = { [target]: withGeneratedTokens(readFileSync(target, 'utf8')), ...brandArtifacts() }
const stale = Object.entries(targets).filter(([path, bytes]) => readFileSync(path, 'utf8') !== bytes)
if (process.argv.includes('--check')) {
  if (stale.length > 0) {
    console.error(`design tokens: ${stale.length} stylesheet/brand artifacts are stale — run \`pnpm tokens:css\``)
    process.exit(1)
  }
  console.log('design tokens: stylesheet and brand artifacts are up to date')
} else {
  for (const [path, bytes] of stale) writeFileSync(path, bytes)
  console.log(`design tokens: wrote ${stale.length} stylesheet/brand artifacts`)
}
